"""Execute and time one trusted full floating solve; preserve process evidence."""
from pathlib import Path
import argparse,json,hashlib,subprocess,time
ap=argparse.ArgumentParser();ap.add_argument('--solver',type=Path,required=True);ap.add_argument('--solver-sha256',required=True);ap.add_argument('--frame',type=Path,required=True);ap.add_argument('--frame-sha256',required=True);ap.add_argument('--out',type=Path,required=True);a=ap.parse_args();H=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();assert H(a.solver)==a.solver_sha256 and H(a.frame/'FULL_FRAME.json')==a.frame_sha256;a.out.mkdir(parents=True,exist_ok=False);cmd=['python',str(a.solver),'--frame',str(a.frame),'--frame-sha256',a.frame_sha256,'--out',str(a.out/'record')];t=time.monotonic();r=subprocess.run(cmd,capture_output=True,text=True);elapsed=time.monotonic()-t;(a.out/'STDOUT.log').write_text(r.stdout);(a.out/'STDERR.log').write_text(r.stderr);assert r.returncode==0,r.stderr;rec=a.out/'record/FULL_SOLVE.json';assert rec.is_file();o={'status':'PASS_ONE_FULL_SOLVE_PROCESS','solver_sha256':a.solver_sha256,'frame_receipt_sha256':a.frame_sha256,'solve_receipt_sha256':H(rec),'process_returncode':r.returncode,'wall_seconds_observed':elapsed,'timing_scope':'One process: imports,1999rowdecode,floatGram/Cholesky/refinement,exactresidual and finite lift. Excludes frame construction/acquisition/packing/CI. Environment-specific observation, not worstcase or full spectral-pipeline benchmark.','physical_promotion':0};(a.out/'PROCESS_RECEIPT.json').write_text(json.dumps(o,indent=2,sort_keys=True)+'\n');print(json.dumps(o))
